    try:
        # Create a circular reference in ExceptionGroup
        # Note: ExceptionGroup is Python 3.11+
        if sys.version_info >= (3, 11):
            eg = ExceptionGroup("group", [ValueError("first")])
            # Force circularity by modifying the exceptions list
            eg.exceptions.append(eg)

            # This should not cause a RecursionError
            Traceback.extract(type(eg), eg, eg.__traceback__)
            print("Circular ExceptionGroup handled successfully.")
        else:
            print("Skipping ExceptionGroup test (requires Python 3.11+)")

